<template><AsyncState :loading="loading" :error="error" :empty="!Object.keys(tasks).length"><template #empty><p>{{ t('project.no_tasks') }}</p></template><main class="page"><PageHeader :title="t('nav.tasks')"/><SectionCard v-for="(task,name) in tasks" :key="name" :title="name"><template #actions><StatusBadge v-if="taskStates[name]" live :tone="tone(taskStates[name])">{{ t(`tasks.status_${taskStates[name] === 'error' ? 'failed' : taskStates[name]}`) }}</StatusBadge><button data-action="run-task" :disabled="taskStates[name] === 'running'" @click="$emit('run',name)">{{ t('btn.run') }}</button></template><dl><dt>Command</dt><dd><CopyableValue :value="task.run"/></dd><template v-if="task.desc"><dt>Description</dt><dd>{{ task.desc }}</dd></template><template v-if="task.dir"><dt>Directory</dt><dd><CopyableValue :value="task.dir"/></dd></template></dl></SectionCard></main></AsyncState></template>
<script setup>import AsyncState from '../components/AsyncState.vue';import CopyableValue from '../components/CopyableValue.vue';import PageHeader from '../components/PageHeader.vue';import SectionCard from '../components/SectionCard.vue';import StatusBadge from '../components/StatusBadge.vue';defineProps({tasks:{type:Object,default:()=>({})},taskStates:{type:Object,default:()=>({})},loading:Boolean,error:{type:[String,Error],default:null},t:{type:Function,required:true}});defineEmits(['run']);const tone=s=>s==='success'?'success':s==='error'?'error':'info';</script>
<style scoped>.page{display:grid;gap:var(--xdev-space-4);min-width:0}dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:10px;margin:0}dt{color:var(--xdev-text-muted)}dd{min-width:0;margin:0}button{padding:7px 12px}@media(max-width:640px){dl{grid-template-columns:1fr}dd{overflow-wrap:anywhere}}</style>
